// Browser ES module entry. The `new URL(literal, import.meta.url)` form is what Vite, webpack 5,
// Rollup and esbuild recognise as a static asset, so bundlers copy the .wasm file and rewrite it.
import { bind } from "./common.js";
import type { WasmApi } from "./types.js";

export * from "./common.js";

type Glue = WasmApi & { default(input: { module_or_path: URL }): Promise<unknown> };

export const { openStore, loadWasm } = bind(async (simd) => {
  if (simd) {
    // @ts-ignore the glue is generated by wasm-bindgen into dist/wasm before this file is used
    const glue: Glue = await import("./wasm/web/simd/warm_wasm.js");
    await glue.default({ module_or_path: new URL("./wasm/web/simd/warm_wasm_bg.wasm", import.meta.url) });
    return glue;
  }
  // @ts-ignore the glue is generated by wasm-bindgen into dist/wasm before this file is used
  const glue: Glue = await import("./wasm/web/scalar/warm_wasm.js");
  await glue.default({ module_or_path: new URL("./wasm/web/scalar/warm_wasm_bg.wasm", import.meta.url) });
  return glue;
});
